package com.bank.ledger.partition;

import org.apache.kafka.clients.producer.Partitioner;
import org.apache.kafka.common.Cluster;
import org.apache.kafka.common.utils.Utils;
import java.util.Map;

public class StickyBucketPartitioner implements Partitioner {

    private int buckets = 24; // fixed logical buckets, independent of partition count

    @Override
    public void configure(Map<String, ?> configs) {
        Object b = configs.get("ledger.buckets");
        if (b != null) buckets = Integer.parseInt(b.toString());
    }

    @Override
    public int partition(String topic, Object key, byte[] keyBytes,
                         Object value, byte[] valueBytes, Cluster cluster) {
        int numPartitions = cluster.partitionCountForTopic(topic);
        if (keyBytes == null) {
            // null key => round-robin is fine, no ordering expectation
            return Utils.toPositive(Utils.murmur2(valueBytes)) % numPartitions;
        }
        // Hash the key into a FIXED number of logical buckets first,
        // then map buckets onto the current partitions deterministically.
        int bucket = Utils.toPositive(Utils.murmur2(keyBytes)) % buckets;
        return bucket % numPartitions;
    }

    @Override
    public void close() { }
}
