package com.bank.ledger.demo;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class PartitionRemapDemo {

    private static final Logger log = Logger.getLogger(PartitionRemapDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        List<String> accounts = List.of("SAV2001", "CUR3001", "SAV2002",
                "SAV2003", "CUR3002", "SAV2004", "CUR3003", "SAV2005");

        DefaultPartitioner def = new DefaultPartitioner();
        log.info("=== Default partitioner: how many keys move when 6 -> 12? ===");
        int moved = 0;
        for (String acct : accounts) {
            int p6 = def.partition(acct, 6);
            int p12 = def.partition(acct, 12);
            boolean movedKey = p6 != p12;
            if (movedKey) moved++;
            log.info(String.format("account=%s  p@6=%d  p@12=%d  moved=%s",
                    acct, p6, p12, movedKey));
        }
        int finalMoved = moved;
        log.warning(() -> finalMoved + " of " + accounts.size() + " keys REMAPPED (ordering risk)");

        log.info("=== Sticky bucket partitioner: stable placement across 6 -> 12 ===");
        StickyBucketPartitioner sticky = new StickyBucketPartitioner(24);
        int stableMoved = 0;
        for (String acct : accounts) {
            int p6 = sticky.partition(acct, 6);
            int p12 = sticky.partition(acct, 12);
            if (p6 != p12) stableMoved++;
        }
        int fsm = stableMoved;
        log.info(() -> "sticky keys remapped = " + fsm + " (bucket owner changes only, bounded)");

        log.info("=== Ordering break demo for a remapped key ===");
        LedgerReplay.demonstrate(log);
    }
}

