class DefaultPartitioner {
    int partition(String key, int numPartitions) {
        return toPositive(murmur2(key.getBytes())) % numPartitions;
    }
    // simplified murmur2 for the demo
    static int murmur2(byte[] data) {
        int length = data.length, seed = 0x9747b28c, m = 0x5bd1e995, r = 24;
        int h = seed ^ length;
        int len4 = length >> 2;
        for (int i = 0; i < len4; i++) {
            int i4 = i << 2;
            int k = (data[i4] & 0xff) | ((data[i4 + 1] & 0xff) << 8)
                    | ((data[i4 + 2] & 0xff) << 16) | ((data[i4 + 3] & 0xff) << 24);
            k *= m; k ^= k >>> r; k *= m; h *= m; h ^= k;
        }
        switch (length % 4) {
            case 3: h ^= (data[(length & ~3) + 2] & 0xff) << 16;
            case 2: h ^= (data[(length & ~3) + 1] & 0xff) << 8;
            case 1: h ^= (data[length & ~3] & 0xff); h *= m;
        }
        h ^= h >>> 13; h *= m; h ^= h >>> 15;
        return h;
    }
    static int toPositive(int n) { return n & 0x7fffffff; }
}

// ─── Would be in StickyBucketPartitioner.java (demo copy) ───
class StickyBucketPartitioner {
    private final int buckets;
    StickyBucketPartitioner(int buckets) { this.buckets = buckets; }
    int partition(String key, int numPartitions) {
        int bucket = DefaultPartitioner.toPositive(DefaultPartitioner.murmur2(key.getBytes())) % buckets;
        return bucket % numPartitions;
    }
}

