class LedgerReplay {
    static void demonstrate(Logger log) {
        // Key SAV2001 had CREDIT(seq=1) waiting in old partition 3.
        // After repartition, DEBIT(seq=2) lands in new partition 9 and is read first.
        log.severe("OLD partition 3 still holds: SAV2001 CREDIT seq=1 (unread)");
        log.severe("NEW partition 9 receives:  SAV2001 DEBIT  seq=2 (read first!)");
        log.severe("Consumer applies seq=2 before seq=1 -> balance computed WRONG");
        log.info("Guard: reject out-of-order seq (expected last_seq_no+1) or avoid repartition");
    }
}

